<template>
  <Avatar :size="size" :shape="shape">
    <AvatarImage :src="src" :alt="alt" />
    <AvatarFallback class="uppercase" :delay-ms="fallbackDelayMs ?? 0">{{ fallback }}</AvatarFallback>
  </Avatar>
</template>

<script setup lang="ts">
interface Props {
  src: string;
  alt: string;
  fallback: string;
  size?: 'base' | 'sm' | 'lg' | 'xs' | null | undefined;
  shape?: 'circle' | 'square' | null | undefined;
  /**
   * Delay (ms) before the initials fallback is shown. Defaults to 0 (immediate — unchanged behavior).
   * Set a small value when the same avatar can remount with an already-cached image, so the fast
   * cache load wins the race and the fallback never flashes. Only useful when a `src` is present.
   */
  fallbackDelayMs?: number | null;
}

withDefaults(defineProps<Props>(), {
  size: 'base',
  shape: 'circle',
  fallbackDelayMs: 0,
});
</script>

<style scoped lang="scss"></style>
